import React,{useState,useEffect}from'react';
import{Link}from'react-router-dom';
import logo from '../assets/logovighnaviacademy.png';

export default function Header(){
const[isMobile,setIsMobile]=useState(false);

useEffect(()=>{
const handleResize=()=>setIsMobile(window.innerWidth<=768);
handleResize();
window.addEventListener('resize',handleResize);
return()=>window.removeEventListener('resize',handleResize);
},[]);

return(
<>
<style>{`
.nav-link:hover{
color:#00D2C4!important;
transform:translateY(-2px);
}
.cta-button:hover{
background-color:#00b3a6!important;
box-shadow:0 0 18px rgba(0,210,196,.5);
transform:translateY(-2px) scale(1.03);
}
.logo-container:hover{
transform:translateY(-2px);
box-shadow:0 8px 25px rgba(0,210,196,.25)!important;
}
`}</style>

<nav style={{
backgroundColor:'#070F1E',
borderBottom:'1px solid rgba(255,255,255,.08)',
padding:isMobile?'10px 18px':'12px 42px',
display:'flex',
justifyContent:'space-between',
alignItems:'center',
position:'sticky',
top:0,
zIndex:50,
width:'100%',
boxSizing:'border-box',
minHeight:isMobile?'68px':'78px'
}}>

<Link to="/" style={{
display:'flex',
alignItems:'center',
textDecoration:'none',
flexShrink:0
}}>
<div
className="logo-container"
style={{
width:isMobile?'58px':'68px',
height:isMobile?'58px':'68px',
display:'flex',
alignItems:'center',
justifyContent:'center',
borderRadius:'14px',
overflow:'hidden',
backgroundColor:'#fff',
padding:'4px',
boxSizing:'border-box',
boxShadow:'0 5px 18px rgba(0,210,196,.18)',
transition:'all .3s ease'
}}
>
<img
src={logo}
alt="Vighnavi Academy Logo"
style={{
width:'100%',
height:'100%',
objectFit:'contain',
display:'block',
borderRadius:'10px'
}}
/>
</div>
</Link>

{!isMobile&&(
<div style={{
display:'flex',
alignItems:'center',
gap:'38px',
fontSize:'17px',
fontWeight:'600',
marginLeft:'auto',
marginRight:'40px'
}}>
<Link
to="/"
className="nav-link"
style={{
color:'#d1d5db',
textDecoration:'none',
transition:'all .2s ease'
}}
>
Home
</Link>

<Link
to="/courses"
className="nav-link"
style={{
color:'#d1d5db',
textDecoration:'none',
transition:'all .2s ease'
}}
>
Courses
</Link>

<Link
to="/about"
className="nav-link"
style={{
color:'#d1d5db',
textDecoration:'none',
transition:'all .2s ease'
}}
>
About Us
</Link>

<Link
to="/contact"
className="nav-link"
style={{
color:'#d1d5db',
textDecoration:'none',
transition:'all .2s ease'
}}
>
Contact Us
</Link>
</div>
)}

<div>
<Link
to="/contact"
className="cta-button"
style={{
backgroundColor:'#00D2C4',
color:'#000',
padding:isMobile?'11px 17px':'13px 25px',
borderRadius:'28px',
textDecoration:'none',
fontWeight:'700',
fontSize:isMobile?'13px':'16px',
display:'inline-block',
transition:'all .3s ease',
whiteSpace:'nowrap',
boxShadow:'0 4px 12px rgba(0,210,196,.18)'
}}
>
Book Consultation&nbsp; →
</Link>
</div>

</nav>
</>
);
}
